<?php
require __DIR__.'/../app/bootstrap.php';refresh_user();require_login('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$subject=post_value('subject');$body=trim((string)($_POST['body']??''));if(post_value('action')==='custom'&&$subject!==''&&$body!==''){$key='custom_'.bin2hex(random_bytes(8));$name=substr(post_value('name')?:$subject,0,120);$stmt=db()->prepare('INSERT INTO email_templates(template_key,name,subject,body,is_default) VALUES(?,?,?, ?,0)');$stmt->bind_param('ssss',$key,$name,$subject,$body);$stmt->execute();flash('success','Custom email template created.');}else flash('error','Add a template name, subject, and body.');redirect('/admin/emails.php');}
$templates=db()->query('SELECT * FROM email_templates ORDER BY is_default DESC,name')->fetch_all(MYSQLI_ASSOC);render_header('Emails Management','admin');page_title('Emails Management','Review notification templates and custom messages.');
?><div class="section-heading users-toolbar"><div><div class="eyebrow">NOTIFICATIONS</div><h2>Email templates <span class="count-pill"><?=count($templates)?></span></h2><p>Default templates are system managed and cannot be removed.</p></div><a class="button button-admin" href="#create-template">＋ Create email template</a></div><div class="template-grid"><?php foreach($templates as $t): ?><article class="template-card"><div class="template-card-top"><span class="template-icon">✉</span><?= $t['is_default']?'<span class="template-label">DEFAULT · LOCKED</span>':'<span class="template-label custom-label">CUSTOM</span>'?></div><h3><?=e($t['name'])?></h3><div class="template-subject">Subject: <?=e($t['subject'])?></div><p><?=e(mb_strimwidth($t['body'],0,150,'…'))?></p><details><summary>Preview full template</summary><pre><?=e($t['body'])?></pre></details></article><?php endforeach; ?></div><div class="modal-backdrop" id="create-template"><div class="modal-card"><a class="modal-close" href="/admin/emails.php">×</a><div class="eyebrow">CUSTOM MESSAGE</div><h2>Create email template</h2><p class="muted">Custom templates are saved for reference and future workflows.</p><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="custom"><label>Template name<input name="name" required placeholder="e.g. Collection reminder"></label><label>Subject<input name="subject" required placeholder="Email subject"></label><label>Body<textarea name="body" rows="6" required placeholder="Write the email message..."></textarea></label><button class="button button-admin button-wide">Save custom template</button></form></div></div><?php render_footer();
